def calculate_hashes(
        ast,
        existing_hashes \\ %{},
        filename \\ "foo.ex",
        mass_threshold \\ param_defaults()[:mass_threshold]
      )
      when is_map(existing_hashes) do
    ast
    |> Credo.Code.prewalk(fn
      node, hashes ->
        if mass(node) >= mass_threshold do
          hash = node |> Credo.Code.remove_metadata() |> to_hash
          node_item = %{node: node, filename: filename, mass: nil}
          updated_hashes = Map.update(hashes, hash, [node_item], &[node_item | &1])
          {node, updated_hashes}
        else
          {node, hashes}
        end
      end, existing_hashes)
  end

